 * A parse failure tied to a specific line of the input document. `cli.js`
 * catches this and reports it as `error: line N: <reason>`.
 */
export class ParseError extends Error {
  constructor(line, reason) {
    super(`line ${line}: ${reason}`)
    this.line = line
    this.reason = reason
  }
}

/**
 * Thrown internally by dotted-name parsing when no name token is found.
 * `atStart` distinguishes "no name at all" (used by the top-level key=value
 * line to report `expected key = value`) from "no name after a dot" (always
 * `expected a name`).
 */
export class NameParseFailure extends Error {
  constructor(atStart) {
    super('name parse failure')
    this.atStart = atStart
  }
}
"}

