{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260919T181623Z/cell-uMkwQy/src/lexer.js","content":"import { ParseError } from './errors.js'

const STOP_CHARS = new Set([' ', '\t', '.', '=', ',', '[', ']', '{', '}', '"', "'"])

const PUNCT = {
  '.': 'DOT',
  '=': 'EQUALS',
  ',': 'COMMA',
  '[': 'LBRACKET',
  ']': 'RBRACKET',
  '{': 'LBRACE',
  '}': 'RBRACE',
}

/**
 * Turns one line of the document into a token list. A `#` or `;` outside a
 * quoted string ends the line, but only when it starts a fresh token: a
 * bareword run swallows a `#`/`;` it meets without whitespace before it, so
 * that later grammar checks reject it as invalid text rather than silently
 * truncating the value.
 */
export function tokenizeLine(line, lineNo) {
  const tokens = []
  let i = 0
  const n = line.length
  while (i < n) {
    const c = line[i]
    if (c === ' ' || c === '\t') {
      i++
      continue
    }
    if (c === '#' || c === ';') break
    if (c === '"' || c === "'") {
      const [value, next] = readString(line, i, lineNo)
      tokens.push({ type: 'STRING', value })
      i = next
      continue
    }
    if (PUNCT[c]) {
      tokens.push({ type: PUNCT[c] })
      i++
      continue
    }
    let j = i
    while (j < n && !STOP_CHARS.has(line[j])) j++
    tokens.push({ type: 'BAREWORD', text: line.slice(i, j) })
    i = j
  }
  return tokens
}

function readString(line, start, lineNo) {
  const quote = line[start]
  const n = line.length
  let j = start + 1
  let value = ''
  if (quote === '"') {
    for (;;) {
      if (j >= n) throw new ParseError(lineNo, 'unterminated string')
      const ch = line[j]
      if (ch === '"') return [value, j + 1]
      if (ch === '\\') {
        j++
        if (j >= n) throw new ParseError(lineNo, 'unterminated string')
        const esc = line[j]
        if (esc === '"') { value += '"'; j++ }
        else if (esc === '\\') { value += '\\'; j++ }
        else if (esc === 'n') { value += '\n'; j++ }
        else if (esc === 't') { value += '\t'; j++ }
        else if (esc === 'r') { value += '\r'; j++ }
        else if (esc === '0') { value += '\0'; j++ }
        else if (esc === 'u') {
          const hex = line.slice(j + 1, j + 5)
          if (hex.length === 4 && /^[0-9A-Fa-f]{4}$/.test(hex)) {
            value += String.fromCharCode(parseInt(hex, 16))
            j += 5
          } else {
            throw new ParseError(lineNo, 'invalid escape \\u')
          }
        } else {
          throw new ParseError(lineNo, `invalid escape \\${esc}`)
        }
      } else {
        value += ch
        j++
      }
    }
  } else {
    for (;;) {
      if (j >= n) throw new ParseError(lineNo, 'unterminated string')
      const ch = line[j]
      if (ch === "'") return [value, j + 1]
      value += ch
      j++
    }
  }
}

/** A tiny cursor over a token array. */
export class TokenStream {
  constructor(tokens) {
    this.tokens = tokens
    this.pos = 0
  }

  peek() {
    return this.tokens[this.pos]
  }

  next() {
    return this.tokens[this.pos++]
  }
}
"}

