{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260919T181623Z/cell-uMkwQy/src/tree.js","content":"import { ParseError } from './errors.js'

/**
 * Nodes of the parsed document. A table's `path` is its dotted+bracketed
 * location from the root, used both for error messages and, doubled up, as
 * the basis for the `keys` command output.
 */
export function createTable(path) {
  return { kind: 'table', map: new Map(), headerDefined: false, path }
}

export function createArrayTable(path) {
  return { kind: 'array-table', items: [], path }
}

/** Renders a structured path (key segments and array indices) as text. */
export function joinPath(pathParts) {
  let s = ''
  for (const seg of pathParts) {
    if (seg.type === 'key') s += s === '' ? seg.name : `.${seg.name}`
    else s += `[${seg.i}]`
  }
  return s
}

export function keySeg(path, name) {
  return [...path, { type: 'key', name }]
}

/**
 * Walks through a table along `segments`, creating plain tables as needed
 * and descending into the last element when a segment names an array of
 * tables. Throws when a segment names something that isn't a table.
 */
export function walkIntermediate(startTable, segments, lineNo) {
  let cur = startTable
  for (const seg of segments) {
    const next = cur.map.get(seg)
    if (next === undefined) {
      const t = createTable(keySeg(cur.path, seg))
      cur.map.set(seg, t)
      cur = t
    } else if (next.kind === 'table') {
      cur = next
    } else if (next.kind === 'array-table') {
      cur = next.items[next.items.length - 1]
    } else {
      throw new ParseError(lineNo, `${joinPath(keySeg(cur.path, seg))} is not a table`)
    }
  }
  return cur
}
"}

